/**
 * Validates submitted Docker files and returns detailed feedback
 * @summary Submit a challenge solution
 */
export const getSubmitChallengeUrl = (id: string) => {
  return `/api/challenges/${id}/submit`;
};

export const submitChallenge = async (
  id: string,
  challengeSubmission: ChallengeSubmission,
  options?: RequestInit,
): Promise<ValidationResult> => {
  return customFetch<ValidationResult>(getSubmitChallengeUrl(id), {
    ...options,
    method: "POST",
    headers: { "Content-Type": "application/json", ...options?.headers },
    body: JSON.stringify(challengeSubmission),
  });
};

export const getSubmitChallengeMutationOptions = <
  TError = ErrorType<ErrorResponse>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof submitChallenge>>,
    TError,
    { id: string; data: BodyType<ChallengeSubmission> },
    TContext
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseMutationOptions<
  Awaited<ReturnType<typeof submitChallenge>>,
  TError,
  { id: string; data: BodyType<ChallengeSubmission> },
  TContext
> => {
  const mutationKey = ["submitChallenge"];
  const { mutation: mutationOptions, request: requestOptions } = options
    ? options.mutation &&
      "mutationKey" in options.mutation &&
      options.mutation.mutationKey
      ? options
      : { ...options, mutation: { ...options.mutation, mutationKey } }
    : { mutation: { mutationKey }, request: undefined };

  const mutationFn: MutationFunction<
    Awaited<ReturnType<typeof submitChallenge>>,
    { id: string; data: BodyType<ChallengeSubmission> }
  > = (props) => {
    const { id, data } = props ?? {};

    return submitChallenge(id, data, requestOptions);
  };

  return { mutationFn, ...mutationOptions };
};

export type SubmitChallengeMutationResult = NonNullable<
  Awaited<ReturnType<typeof submitChallenge>>
>;
export type SubmitChallengeMutationBody = BodyType<ChallengeSubmission>;
export type SubmitChallengeMutationError = ErrorType<ErrorResponse>;

/**
 * @summary Submit a challenge solution
 */
export const useSubmitChallenge = <
  TError = ErrorType<ErrorResponse>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof submitChallenge>>,
    TError,
    { id: string; data: BodyType<ChallengeSubmission> },
    TContext
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseMutationResult<
  Awaited<ReturnType<typeof submitChallenge>>,
  TError,
  { id: string; data: BodyType<ChallengeSubmission> },
  TContext
> => {
  return useMutation(getSubmitChallengeMutationOptions(options));
};
